  // Responsive scale calculations based on 1080x1920 reference layout
  const responsiveScale = (width / 1080) * scaleFactor;

  // Layout Dimensions
  const componentWidth = 920 * responsiveScale;
  const componentHeight = 280 * responsiveScale;
